dataSet.query:
SELECT SalesTurnovers.Hotel AS Hotel, BEGINOFPERIOD(SalesTurnovers.AccountingDate, YEAR) AS AccountingYear, BEGINOFPERIOD(SalesTurnovers.AccountingDate, MONTH) AS AccountingMonth, SalesTurnovers.AccountingDate AS AccountingDate, SalesTurnovers.MarketingCode AS MarketingCode, SalesTurnovers.SourceOfBusiness AS SourceOfBusiness, SalesTurnovers.RoomType AS RoomType, SalesTurnovers.Customer AS Customer, SalesTurnovers.Agent AS Agent, SalesTurnovers.Service.ServiceType AS ServiceType, SalesTurnovers.Service AS Service, SalesTurnovers.Client.Citizenship AS Country, SalesTurnovers.RoomRevenueWithoutVATTurnover AS RoomRevenueTurnover, SalesTurnovers.RoomsRentedTurnover AS RoomsRentedTurnover, CASE WHEN SalesTurnovers.RoomsRentedTurnover > 0 THEN SalesTurnovers.RoomRevenueWithoutVATTurnover / SalesTurnovers.RoomsRentedTurnover ELSE 0 END AS ADR INTO CurrentPeriod FROM AccumulationRegister.Sales.Turnovers(BEGINOFPERIOD(&PeriodFrom, DAY), ENDOFPERIOD(&PeriodTo, DAY), DAY, NOT IsCorrection) AS SalesTurnovers WHERE CASE WHEN &Hotel = VALUE(Catalog.Hotels.EmptyRef) OR &Hotel = UNDEFINED THEN TRUE ELSE SalesTurnovers.Hotel = &Hotel END AND CASE WHEN &MarketingCode = VALUE(Catalog.MarketingCodes.EmptyRef) OR &MarketingCode = UNDEFINED THEN TRUE ELSE SalesTurnovers.MarketingCode = &MarketingCode END AND CASE WHEN &SourceOfBusiness = VALUE(Catalog.SourcesOfBusiness.EmptyRef) OR &SourceOfBusiness = UNDEFINED THEN TRUE ELSE SalesTurnovers.SourceOfBusiness = &SourceOfBusiness END AND CASE WHEN &RoomType = VALUE(Catalog.RoomTypes.EmptyRef) OR &RoomType = UNDEFINED THEN TRUE ELSE SalesTurnovers.RoomType = &RoomType END AND CASE WHEN &Customer = VALUE(Catalog.Customers.EmptyRef) OR &Customer = UNDEFINED THEN TRUE ELSE SalesTurnovers.Customer = &Customer END AND CASE WHEN &Agent = VALUE(Catalog.Customers.EmptyRef) OR &Agent = UNDEFINED THEN TRUE ELSE SalesTurnovers.Agent = &Agent END AND CASE WHEN &Citizenship = VALUE(Catalog.Countries.EmptyRef) OR &Citizenship = UNDEFINED THEN TRUE ELSE SalesTurnovers.Client.Citizenship = &Citizenship END AND (SalesTurnovers.RoomRevenueTurnover > 0 OR SalesTurnovers.RoomsRentedTurnover > 0)
UNION ALL
SELECT SalesForecastTurnovers.Hotel, BEGINOFPERIOD(SalesForecastTurnovers.AccountingDate, YEAR), BEGINOFPERIOD(SalesForecastTurnovers.AccountingDate, MONTH), SalesForecastTurnovers.AccountingDate, SalesForecastTurnovers.MarketingCode, SalesForecastTurnovers.SourceOfBusiness, SalesForecastTurnovers.RoomType, SalesForecastTurnovers.Customer, SalesForecastTurnovers.Agent, SalesForecastTurnovers.Service.ServiceType, SalesForecastTurnovers.Service, SalesForecastTurnovers.Client.Citizenship, SalesForecastTurnovers.RoomRevenueWithoutVATTurnover, SalesForecastTurnovers.RoomsRentedTurnover, CASE WHEN SalesForecastTurnovers.RoomsRentedTurnover > 0 THEN SalesForecastTurnovers.RoomRevenueWithoutVATTurnover / SalesForecastTurnovers.RoomsRentedTurnover ELSE 0 END FROM AccumulationRegister.SalesForecast.Turnovers(BEGINOFPERIOD(&ForecastPeriodFrom, DAY), ENDOFPERIOD(&ForecastPeriodTo, DAY), DAY, &UseForecast = TRUE) AS SalesForecastTurnovers WHERE CASE WHEN &Hotel = VALUE(Catalog.Hotels.EmptyRef) OR &Hotel = UNDEFINED THEN TRUE ELSE SalesForecastTurnovers.Hotel = &Hotel END AND CASE WHEN &MarketingCode = VALUE(Catalog.MarketingCodes.EmptyRef) OR &MarketingCode = UNDEFINED THEN TRUE ELSE SalesForecastTurnovers.MarketingCode = &MarketingCode END AND CASE WHEN &SourceOfBusiness = VALUE(Catalog.SourcesOfBusiness.EmptyRef) OR &SourceOfBusiness = UNDEFINED THEN TRUE ELSE SalesForecastTurnovers.SourceOfBusiness = &SourceOfBusiness END AND CASE WHEN &RoomType = VALUE(Catalog.RoomTypes.EmptyRef) OR &RoomType = UNDEFINED THEN TRUE ELSE SalesForecastTurnovers.RoomType = &RoomType END AND CASE WHEN &Customer = VALUE(Catalog.Customers.EmptyRef) OR &Customer = UNDEFINED THEN TRUE ELSE SalesForecastTurnovers.Customer = &Customer END AND CASE WHEN &Agent = VALUE(Catalog.Customers.EmptyRef) OR &Agent = UNDEFINED THEN TRUE ELSE SalesForecastTurnovers.Agent = &Agent END AND CASE WHEN &Citizenship = VALUE(Catalog.Countries.EmptyRef) OR &Citizenship = UNDEFINED THEN TRUE ELSE SalesForecastTurnovers.Client.Citizenship = &Citizenship END AND (SalesForecastTurnovers.RoomRevenueTurnover > 0 OR SalesForecastTurnovers.RoomsRentedTurnover > 0) ;
//////////////////////////////////////////////////////////////////////////////// SELECT SalesTurnovers.Hotel AS Hotel, SalesTurnovers.AccountingDate AS AccountingDate, SalesTurnovers.MarketingCode AS MarketingCode, SalesTurnovers.SourceOfBusiness AS SourceOfBusiness, SalesTurnovers.RoomType AS RoomType, SalesTurnovers.Customer AS Customer, SalesTurnovers.Agent AS Agent, SalesTurnovers.Service.ServiceType AS ServiceType, SalesTurnovers.Service AS Service, SalesTurnovers.Client.Citizenship AS Country, SalesTurnovers.RoomRevenueWithoutVATTurnover AS RoomRevenueTurnover, SalesTurnovers.RoomsRentedTurnover AS RoomsRentedTurnover, CASE WHEN SalesTurnovers.RoomsRentedTurnover > 0 THEN SalesTurnovers.RoomRevenueWithoutVATTurnover / SalesTurnovers.RoomsRentedTurnover ELSE 0 END AS ADR, BEGINOFPERIOD(SalesTurnovers.AccountingDate, YEAR) AS AccountingYear, BEGINOFPERIOD(SalesTurnovers.AccountingDate, MONTH) AS AccountingMonth INTO AdditionalPeriod FROM AccumulationRegister.Sales.Turnovers( BEGINOFPERIOD(&AddPeriodFrom, DAY), ENDOFPERIOD(&AddPeriodTo, DAY), Day, &UseAdditional = TRUE AND NOT IsCorrection AND ISNULL(GuestGroup.CreateDate, DATETIME(1, 1, 1)) < DATEADD(DATEADD(&ForecastPeriodFrom, MONTH, -12), DAY, 1)) AS SalesTurnovers WHERE CASE WHEN &Hotel = VALUE(Catalog.Hotels.EmptyRef) OR &Hotel = UNDEFINED THEN TRUE ELSE SalesTurnovers.Hotel = &Hotel END AND CASE WHEN &MarketingCode = VALUE(Catalog.MarketingCodes.EmptyRef) OR &MarketingCode = UNDEFINED THEN TRUE ELSE SalesTurnovers.MarketingCode = &MarketingCode END AND CASE WHEN &SourceOfBusiness = VALUE(Catalog.SourcesOfBusiness.EmptyRef) OR &SourceOfBusiness = UNDEFINED THEN TRUE ELSE SalesTurnovers.SourceOfBusiness = &SourceOfBusiness END AND CASE WHEN &RoomType = VALUE(Catalog.RoomTypes.EmptyRef) OR &RoomType = UNDEFINED THEN TRUE ELSE SalesTurnovers.RoomType = &RoomType END AND CASE WHEN &Customer = VALUE(Catalog.Customers.EmptyRef) OR &Customer = UNDEFINED THEN TRUE ELSE SalesTurnovers.Customer = &Customer END AND CASE WHEN &Agent = VALUE(Catalog.Customers.EmptyRef) OR &Agent = UNDEFINED THEN TRUE ELSE SalesTurnovers.Agent = &Agent END AND CASE WHEN &Citizenship = VALUE(Catalog.Countries.EmptyRef) OR &Citizenship = UNDEFINED THEN TRUE ELSE SalesTurnovers.Client.Citizenship = &Citizenship END AND (SalesTurnovers.RoomRevenueTurnover > 0 OR SalesTurnovers.RoomsRentedTurnover > 0) ;
//////////////////////////////////////////////////////////////////////////////// SELECT DISTINCT ISNULL(CurrentPeriod.AccountingDate, AdditionalPeriod.AccountingDate) AS AccountingDate, BEGINOFPERIOD(ISNULL(CurrentPeriod.AccountingDate, AdditionalPeriod.AccountingDate), MONTH) AS AccountingMonth, BEGINOFPERIOD(ISNULL(CurrentPeriod.AccountingDate, AdditionalPeriod.AccountingDate), YEAR) AS AccountingYear INTO AllDates FROM CurrentPeriod AS CurrentPeriod FULL JOIN AdditionalPeriod AS AdditionalPeriod ON CurrentPeriod.AccountingDate = AdditionalPeriod.AccountingDate ;
//////////////////////////////////////////////////////////////////////////////// SELECT ISNULL(CurrentPeriod.Hotel, AdditionalPeriod.Hotel) AS Hotel, ISNULL(CurrentPeriod.MarketingCode, AdditionalPeriod.MarketingCode) AS MarketingCode, ISNULL(CurrentPeriod.SourceOfBusiness, AdditionalPeriod.SourceOfBusiness) AS SourceOfBusiness, ISNULL(CurrentPeriod.RoomType, AdditionalPeriod.RoomType) AS RoomType, ISNULL(CurrentPeriod.Customer, AdditionalPeriod.Customer) AS Customer, ISNULL(CurrentPeriod.Agent, AdditionalPeriod.Agent) AS Agent, ISNULL(CurrentPeriod.ServiceType, AdditionalPeriod.ServiceType) AS ServiceType, ISNULL(CurrentPeriod.Service, AdditionalPeriod.Service) AS Service, ISNULL(CurrentPeriod.Country, AdditionalPeriod.Country) AS Country, CurrentPeriod.RoomRevenueTurnover AS RoomRevenueTurnover, CurrentPeriod.RoomsRentedTurnover AS RoomsRentedTurnover, CurrentPeriod.ADR AS ADR, AdditionalPeriod.RoomRevenueTurnover AS RoomRevenueTurnoverAdditional, AdditionalPeriod.RoomsRentedTurnover AS RoomsRentedTurnoverAdditional, AdditionalPeriod.ADR AS ADRAdditional, CurrentPeriod.AccountingDate AS AccountingDate, CurrentPeriod.AccountingMonth AS AccountingMonth, CurrentPeriod.AccountingYear AS AccountingYear, AdditionalPeriod.AccountingYear AS AccountingYearAdditional, AdditionalPeriod.AccountingMonth AS AccountingMonthAdditional, AdditionalPeriod.AccountingDate AS AccountingDateAdditional FROM AllDates AS AllDates LEFT JOIN CurrentPeriod AS CurrentPeriod ON AllDates.AccountingDate = CurrentPeriod.AccountingDate LEFT JOIN AdditionalPeriod AS AdditionalPeriod ON AllDates.AccountingDate = AdditionalPeriod.AccountingDate
